<?php
namespace App\Http\Controllers;
use App\Services\{CalendarImport,ContactImportCache,MailContacts,SalonStore,Tenant,ImportStaging,WorkspaceAccess};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Http,DB};
use Carbon\CarbonImmutable as Date;

final class CalendarImportController
{
 private function owner(Request $r):int{return WorkspaceAccess::admin($r);}
 private function key(Request $r,string $id):string{return ImportStaging::key($r,'calendar-import',$id);}
 private function save(Request $r,array $value):string{return ImportStaging::create($r,'calendar-import',$value);}
 private function read(Request $r,string $id):array{return ImportStaging::read($r,'calendar-import',$id);}
 private function get(string $token,string $path,array $query=[]):array{$r=Http::connectTimeout(5)->timeout(20)->withToken($token)->get('https://www.googleapis.com/calendar/v3/'.$path,$query);abort_unless($r->successful(),422,'A Google Naptár lekérése nem sikerült. Ellenőrizd a megadott engedélyt.');return $r->json();}
 public function start(Request $r){$owner=$this->owner($r);$keys=MailContacts::credentials('google');abort_unless($keys['id']&&$keys['secret'],503,'A Google-kapcsolat még nincs beállítva.');$state=bin2hex(random_bytes(32));$verifier=bin2hex(random_bytes(32));$r->session()->put('calendar_import_oauth',compact('owner','state','verifier')+['expires'=>time()+600]);return redirect()->away('https://accounts.google.com/o/oauth2/v2/auth?'.http_build_query(['client_id'=>$keys['id'],'redirect_uri'=>rtrim(config('app.url'),'/').'/auth/calendar-import/callback','response_type'=>'code','scope'=>'https://www.googleapis.com/auth/calendar.calendarlist.readonly https://www.googleapis.com/auth/calendar.events.readonly','state'=>$state,'code_challenge'=>rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'='),'code_challenge_method'=>'S256','prompt'=>'consent']));}
 public function callback(Request $r){$owner=$this->owner($r);$saved=$r->session()->pull('calendar_import_oauth');$target='/?provider='.$owner.'&calendarImport=';if(!$saved||$saved['expires']<time()||$saved['owner']!==$owner||!is_string($r->query('state'))||!hash_equals($saved['state'],$r->query('state'))||!$r->filled('code'))return redirect($target.'error');try{$keys=MailContacts::credentials('google');$response=Http::timeout(20)->asForm()->post('https://oauth2.googleapis.com/token',['client_id'=>$keys['id'],'client_secret'=>$keys['secret'],'code'=>$r->query('code'),'code_verifier'=>$saved['verifier'],'grant_type'=>'authorization_code','redirect_uri'=>rtrim(config('app.url'),'/').'/auth/calendar-import/callback']);if(!$response->successful()||!$response->json('access_token'))return redirect($target.'error');$token=$response->json('access_token');$calendars=[];$page=null;do{$list=$this->get($token,'users/me/calendarList',array_filter(['maxResults'=>250,'pageToken'=>$page]));foreach($list['items']??[] as $c)$calendars[]=['id'=>$c['id'],'name'=>$c['summary']??$c['id'],'timezone'=>$c['timeZone']??'Europe/Budapest'];$page=$list['nextPageToken']??null;if(count($calendars)>1000)throw new \RuntimeException();}while($page);$id=$this->save($r,['type'=>'connection','token'=>$token,'calendars'=>$calendars]);return redirect($target.$id);}catch(\Throwable){return redirect($target.'error');}}
 public function calendars(Request $r,string $id){$d=$this->read($r,$id);abort_unless(($d['type']??'')==='connection',422);return response()->json(['calendars'=>$d['calendars']]);}
 public function events(Request $r){$v=$r->validate(['id'=>'required|uuid','calendar'=>'required|string|max:1000','from'=>'required|date_format:Y-m-d|after_or_equal:today','to'=>'required|date_format:Y-m-d|after_or_equal:from']);abort_if(Date::parse($v['from'])->diffInDays(Date::parse($v['to']))>62,422,'Legfeljebb 62 napot válassz.');$d=$this->read($r,$v['id']);abort_unless(($d['type']??'')==='connection',422);$calendar=collect($d['calendars'])->firstWhere('id',$v['calendar']);abort_unless($calendar,422);$events=[];$page=null;$pages=0;do{$reply=$this->get($d['token'],'calendars/'.rawurlencode($v['calendar']).'/events',array_filter(['timeMin'=>Date::parse($v['from'],'Europe/Budapest')->toIso8601String(),'timeMax'=>Date::parse($v['to'],'Europe/Budapest')->addDay()->toIso8601String(),'singleEvents'=>'true','showDeleted'=>'false','maxResults'=>1000,'pageToken'=>$page]));foreach($reply['items']??[] as $e){$event=CalendarImport::event($e,$calendar['timezone']);if($event){$min=Date::parse($v['from'],'Europe/Budapest')->utc();$max=Date::parse($v['to'],'Europe/Budapest')->addDay()->utc();if(Date::parse($event['start'])<$min)$event['start']=$min->toIso8601String();if(Date::parse($event['end'])>$max)$event['end']=$max->toIso8601String();if(Date::parse($event['end'])>Date::parse($event['start']))$events[]=$event;}}$page=$reply['nextPageToken']??null;abort_if(count($events)>2000||(++$pages>=5&&$page),422,'Túl sok esemény. Válassz rövidebb időszakot.');}while($page);// Enrich old busy-cache entries only where a unique, freshly read event identifies the same range.
 $byRange=[];foreach($events as $event)$byRange[strtotime($event['start']).':'.strtotime($event['end'])][]=$event['eventId'];
 foreach(DB::table('calendar_connections')->where('provider_id',$this->owner($r))->where('owner_type','staff')->where('calendar_id',$v['calendar'])->get() as $connection){$ranges=json_decode($connection->busy??'[]',true);$changed=false;foreach($ranges as &$range){$ids=$byRange[$range['start'].':'.$range['end']]??[];if(empty($range['eventId'])&&count($ids)===1){$range['eventId']=$ids[0];$range['calendarId']=$v['calendar'];$changed=true;}}unset($range);if($changed)DB::table('calendar_connections')->where('id',$connection->id)->where('busy',$connection->busy)->update(['busy'=>json_encode($ranges)]);}
 $id=$this->save($r,['type'=>'events','calendar'=>$v['calendar'],'events'=>$events]);return response()->json(['id'=>$id,'events'=>$events]);}
 public function preview(Request $r){$v=$r->validate(['id'=>'required|uuid','choices'=>'required|array|min:1|max:2000','choices.*.index'=>'required|integer|min:0|max:1999|distinct','choices.*.mode'=>'required|in:block,booking','choices.*.staff'=>'required|string|max:80','choices.*.service'=>'nullable|string|max:80','choices.*.contact'=>'required|boolean','choices.*.name'=>'nullable|string|max:150','choices.*.phone'=>'nullable|string|max:100','choices.*.email'=>'nullable|email|max:200','choices.*.clientId'=>'nullable|string|max:80','policy'=>'sometimes|in:fill,overwrite,skip']);$d=$this->read($r,$v['id']);abort_unless(($d['type']??'')==='events',422);$s=app(SalonStore::class)->read();$policy=$v['policy']??'fill';$items=[];$result=['blocks'=>0,'bookings'=>0,'contacts'=>0,'skipped'=>0];$matches=[];$previewState=$s;
 foreach($v['choices'] as $choice){try{$copy=$previewState;$count=CalendarImport::apply($copy,$d['events'],[$choice],$d['calendar'],$policy);$previewState=$copy;foreach($result as $k=>$_)$result[$k]+=$count[$k];$items[]=['index'=>$choice['index'],'status'=>$count['skipped']?'same':(($policy==='overwrite'&&$count['blocks']+$count['bookings'])?'update':'new'),'name'=>$d['events'][$choice['index']]['title']??'','message'=>$count['skipped']?'Már átvett esemény':'Átvehető'];}
 catch(\InvalidArgumentException $e){$m=\App\Services\ContactImport::inspect($s['clients'],$choice,$policy,$choice['clientId']??null);$items[]=['index'=>$choice['index'],'status'=>'conflict','name'=>$choice['name']??'','message'=>$e->getMessage(),'candidates'=>$m['candidates']??[]];}
 if($choice['contact']){$m=\App\Services\ContactImport::inspect($s['clients'],$choice,$policy,$choice['clientId']??null);$matches[]=['name'=>$choice['name'],'message'=>$m['message'],'changes'=>$m['changes']];}}
 return response()->json($result+['matches'=>$matches,'items'=>$items,'summary'=>\App\Services\ImportPolicy::summary($items),'policy'=>$policy]);}
 public function commit(Request $r){$v=$r->validate(['id'=>'required|uuid','choices'=>'required|array|min:1|max:2000','choices.*.index'=>'required|integer|min:0|max:1999|distinct','choices.*.mode'=>'required|in:block,booking','choices.*.staff'=>'required|string|max:80','choices.*.service'=>'nullable|string|max:80','choices.*.contact'=>'required|boolean','choices.*.name'=>'nullable|string|max:150','choices.*.phone'=>'nullable|string|max:100','choices.*.email'=>'nullable|email|max:200','choices.*.clientId'=>'nullable|string|max:80','policy'=>'sometimes|in:fill,overwrite,skip']);$key=$this->key($r,$v['id']);$result=ContactImportCache::store()->lock($key.':lock',30)->block(3,function()use($r,$v,$key){$d=$this->read($r,$v['id']);if(isset($d['result']))return $d['result'];abort_unless(($d['type']??'')==='events',422);$result=app(SalonStore::class)->mutate(fn(&$s)=>CalendarImport::apply($s,$d['events'],$v['choices'],$d['calendar'],$v['policy']??'fill'),false);ImportStaging::put($key,['result'=>$result]);return $result;});return response()->json($result);}
}
